"""Versioned editorial source for the remaining Russian document forms.

These are independently written, scoped forms, not government-approved forms.
Samples are fictional QA data and are never used as production field defaults.
"""
import json, copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PATH=ROOT/'assets/word/fixed_templates_ru.json'
C=json.loads(PATH.read_text())
COMMON={'city':('Место составления','Казань'),'date':('Дата документа','19 октября 2026 года')}
def make(kind,title,scope,fields,blocks,*,notice='',reject='',sources=()):
    fs=dict(COMMON);fs.update(fields)
    C[kind]={'version':kind+'_ru_v1','file':kind+'_ru_v1.docx','title':title,'label':title,
        'scope':scope,'explicit_ru':False,'notice':notice,'reject_pattern':reject,
        'fields':{k:v[0] for k,v in fs.items()},'sample':{k:v[1] for k,v in fs.items()},
        'max_cost_pages':2,'qa_max_pages':3,'sources':list(sources),
        'blocks':([['p',notice]] if notice else [])+[['p','Место: {city}. Дата: {date}.']]+blocks}
def p(t):return ['p',t]
def h(t):return ['h',t]
def parties(a,b):
    return {'party_a':(a,'Иванов Алексей Сергеевич'),'details_a':('Реквизиты первой стороны','Паспорт 92 00 123456, выдан УМВД России по г. Казани 20.04.2020; адрес: Казань, ул. Учебная, д. 1'),
            'party_b':(b,'Петрова Анна Викторовна'),'details_b':('Реквизиты второй стороны','Паспорт 92 00 654321, выдан УМВД России по г. Казани 15.05.2020; адрес: Казань, ул. Учебная, д. 2')}
def biz(a,b):
    return {'party_a':(a,'ООО «Учебная мастерская»'),'details_a':('Реквизиты первой стороны','ИНН 0000000000; адрес: Казань, ул. Учебная, д. 1; счёт 00000000000000000000'),
            'signer_a':('Подписант первой стороны и полномочия','директор Иванов Алексей Сергеевич, действует на основании устава'),
            'party_b':(b,'ООО «Контрольный пример»'),'details_b':('Реквизиты второй стороны','ИНН 1111111111; адрес: Казань, ул. Учебная, д. 2; счёт 11111111111111111111'),
            'signer_b':('Подписант второй стороны и полномочия','директор Петрова Анна Викторовна, действует на основании устава')}
def intro(a,b,business=False):
    return [p(a+': {party_a}. '+('Подписант и основание полномочий: {signer_a}.' if business else '')),
            p(b+': {party_b}. '+('Подписант и основание полномочий: {signer_b}.' if business else ''))]
def end():
    return [h('Реквизиты и подписи'),p('Первая сторона: {party_a}. {details_a}.'),p('Подпись ____________________'),
            p('Вторая сторона: {party_b}. {details_b}.'),p('Подпись ____________________')]
GK1='https://www.consultant.ru/document/cons_doc_LAW_5142/'
GK2='https://www.consultant.ru/document/cons_doc_LAW_9027/'
